import {genesisPanel,initGenesisPanel} from "./genesis-structure.js";
const $=s=>document.querySelector(s),esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const fmt=n=>n<0?Math.abs(n)+" a. C.":n+" d. C.";const dateText=d=>d.label|| (d.precision==="undated"?"Sin datación verificable":d.precision==="debated"?"Cronología debatida":(d.precision==="approximate"?"c. ":"")+fmt(d.startYear)+" – "+(d.endYear==null?"actualidad":fmt(d.endYear)));const drawings={primeval:["Creación","Edén","Diluvio","Babel"],patriarchs:["Abraham","Isaac","Jacob","José"],"exodus-judges":["Egipto","Éxodo","Sinaí","Jueces"],monarchy:["Saúl","David","Salomón","Israel / Judá"],"exile-restoration":["Jerusalén","Exilio","Retorno","Templo"],"second-temple":["Persia","Helenismo","Roma","Judea"],apostolic:["Jesús","Jerusalén","Antioquía","Comunidades"],patristic:["Padres griegos","Padres latinos","Nicea","Calcedonia"],medieval:["Monacato","Oriente","Occidente","Escolástica"],modern:["Reformas","Traducciones","Misiones","Estudios bíblicos"]};function diagram(era){const items=drawings[era.id]||[];const w=560,h=136;return '<figure class="diagram"><svg role="img" aria-label="Diagrama de '+esc(era.title)+'" viewBox="0 0 '+w+' '+h+'" xmlns="http://www.w3.org/2000/svg"><path d="M44 69 H516" fill="none" stroke="#82998b" stroke-width="2"/>'+items.map((name,i)=>{const x=60+i*145;return '<circle cx="'+x+'" cy="69" r="9" fill="'+esc(era.color)+'" stroke="#183529" stroke-width="1.5"/><text x="'+x+'" y="'+(i%2?105:39)+'" font-size="14" fill="#344e3e" font-family="system-ui" text-anchor="middle">'+esc(name)+'</text>'}).join("")+'</svg><figcaption>Esquema editorial de procesos y personajes; no representa intervalos de duración exactos.</figcaption></figure>'}async function main(){const response=await fetch(new URL("./data/history/timeline.json",import.meta.url),{cache:"no-store"});if(!response.ok)throw Error("No se pudo cargar la cronología");const data=await response.json();const eras=[...data.eras].sort((a,b)=>a.order-b.order);const slugs={primeval:"historia-primigenia",patriarchs:"patriarcas","exodus-judges":"exodo-y-jueces",monarchy:"monarquia","exile-restoration":"exilio-y-restauracion","second-temple":"segundo-templo",apostolic:"era-apostolica",patristic:"cristianismo-antiguo",medieval:"cristianismo-medieval",modern:"reformas-y-modernidad"};const basePath=new URL("./history/",import.meta.url).pathname;const fromPath=location.pathname.slice(basePath.length).split("/").filter(Boolean)[0];let active=Object.keys(slugs).find(id=>slugs[id]===fromPath)||new URL(location.href).searchParams.get("era");if(!eras.some(e=>e.id===active))active=eras[0].id;const select=(id,move=false,fromHistory=false)=>{const changed=active!==id;active=id;document.querySelector(".kb-history-app")?.classList.remove("is-reading");const i=eras.findIndex(e=>e.id===id),era=eras[i],bib=i<6;$("#scale").innerHTML=eras.map((e,j)=>'<button aria-label="'+esc(e.title)+'" title="'+esc(e.title)+'" class="'+(e.date.precision==="undated"||e.date.precision==="debated"?"uncertain ":"")+(j===i?"active":"")+'" style="--c:'+esc(e.color)+'" data-id="'+esc(e.id)+'"></button>').join("");$("#scale-numbers").innerHTML=eras.map((e,j)=>'<button class="'+(i===j?"active":"")+'" data-id="'+esc(e.id)+'" aria-label="Era '+(j+1)+': '+esc(e.title)+'" aria-current="'+(i===j?'step':'false')+'">'+(j+1)+'</button>').join("");$("#group-label").textContent=bib?"Historia bíblica":"Cristianismo";$("#group-count").textContent=bib?"6 eras":"4 eras";$("#selector .group-title").classList.toggle("christian",!bib);$("#era-strip").innerHTML=eras.map((e,j)=>'<button class="era" data-id="'+esc(e.id)+'" aria-pressed="'+(j===i)+'" style="--era-color:'+esc(e.color)+'"><span class="era-top"><span class="era-group">'+(j<6?"Historia bíblica":"Cristianismo")+'</span><span class="era-count">'+(j+1)+' de '+eras.length+'</span></span><span class="era-title">'+esc(e.title)+'</span><span class="era-date">'+(e.date.precision==="undated"||e.date.precision==="debated"?'<span class="kb-hatch" aria-hidden="true"></span>':"")+esc(dateText(e.date))+'</span></button>').join("");const ev=data.events.filter(e=>e.eraId===id).sort((a,b)=>a.order-b.order);$("#era-detail").style.setProperty("--gc",bib?"var(--green)":"var(--gold)");const stories=(data.stories||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const currentStory=stories.find(x=>location.pathname.includes("/"+x.id+"/"));const periods=(data.subEras||[]).filter(x=>x.eraId===id).sort((a,b)=>a.order-b.order);const periodNav=periods.length?'<nav class="kb-periods" aria-label="Periodos de la era"><button type="button" class="kb-period active" data-period="all" aria-pressed="true">Todos</button>'+periods.map(p=>'<button type="button" class="kb-period" data-period="'+esc(p.id)+'" aria-pressed="false">'+esc(p.title)+'</button>').join("")+'</nav>':"";const bookMeta={genesis:{name:"Génesis",category:"Ley",chapters:50,range:"Génesis 1–50"},exodo:{name:"Éxodo",category:"Ley",chapters:40},levitico:{name:"Levítico",category:"Ley",chapters:27},numeros:{name:"Números",category:"Ley",chapters:36},deuteronomio:{name:"Deuteronomio",category:"Ley",chapters:34},josue:{name:"Josué",category:"Históricos",chapters:24},jueces:{name:"Jueces",category:"Históricos",chapters:21},rut:{name:"Rut",category:"Históricos",chapters:4}};const bookNav=era.bookIds.length?'<div class="kb-history-books"><p class="kb-section-label">Libros relacionados</p><div class="kb-history-book-row">'+era.bookIds.map(b=>{const m=bookMeta[b]||{name:b.replace(/-/g," "),category:"Libro bíblico"};const range=era.relatedTexts?.find(t=>t.toLowerCase().includes(m.name.toLowerCase()))||era.subtitle;return '<a class="kb-history-book" href="'+new URL("./index.html",import.meta.url).pathname+'?book='+encodeURIComponent(b)+'&chapter=1"><span class="kb-history-book-bar" aria-hidden="true"></span><span class="kb-history-book-info"><strong>'+esc(m.name)+'</strong><small>'+esc(m.chapters?m.chapters+' capítulos · '+(range||m.category):range||m.category)+'</small></span><span class="kb-history-book-tag">'+esc(m.category)+'</span><span class="kb-history-book-arrow" aria-hidden="true">›</span></a>'}).join("")+'</div></div>':"";const card=x=>'<a class="kb-story" href="'+basePath+slugs[id]+'/'+x.id+'/"><div class="kb-story-art kb-art-'+esc(x.visual)+'">'+(x.cover?.src?'<img class="kb-story-image" src="'+esc(new URL("./"+x.cover.src,import.meta.url).pathname)+'" alt="'+esc(x.cover.alt||x.title)+'" loading="lazy" decoding="async">':'<b aria-hidden="true">'+({cosmos:"✺",garden:"❧",brothers:"◈",city:"▥",flood:"≋",tower:"▤"}[x.visual]||"✦")+'</b>')+'</div><div class="kb-story-copy"><small>'+esc(x.reference)+'</small><h3>'+esc(x.title)+'</h3></div></a>';if(stories.length){$("#era-detail").innerHTML=currentStory?'<a class="kb-story-back" href="'+basePath+slugs[id]+'/">← Todas las historias</a><p class="plate-kicker">'+esc(era.title)+' · '+currentStory.order+' de '+stories.length+'</p><h2>'+esc(currentStory.title)+'</h2><p class="plate-sub">'+esc(currentStory.reference)+'</p><p class="summary">'+esc(currentStory.summary)+'</p><a class="kb-read" href="'+new URL("./index.html",import.meta.url).pathname+'?book=genesis&chapter='+currentStory.chapter+'">Leer en Génesis ↗</a>':'<p class="plate-kicker">'+(bib?"Historia bíblica":"Cristianismo")+' · era '+(i+1)+' de '+eras.length+'</p><h2>'+esc(era.title)+'</h2>'+bookNav+genesisPanel(data,id,basePath,slugs[id])+periodNav+'<h3 class="kb-stories-heading">Historias de la era '+esc(era.title)+'</h3><div class="kb-story-grid">'+stories.map(card).join("")+'</div>';if(!currentStory)initGenesisPanel($("#era-detail"));if(!currentStory&&periods.length){document.querySelectorAll(".kb-period").forEach(btn=>btn.addEventListener("click",()=>{const period=btn.dataset.period;document.querySelectorAll(".kb-period").forEach(b=>{const selected=b===btn;b.classList.toggle("active",selected);b.setAttribute("aria-pressed",String(selected))});document.querySelectorAll(".kb-story").forEach(card=>{const story=stories.find(x=>card.getAttribute("href").endsWith("/"+x.id+"/"));card.hidden=period!=="all"&&story?.subEraId!==period})}))}const target=basePath+slugs[id]+'/';if(!currentStory&&location.pathname!==target&&!fromHistory)history.pushState({era:id},'',target);if(changed)document.querySelector(".kb-history-app .page")?.scrollTo({top:0,behavior:"instant"});return}$("#era-detail").innerHTML='<p class="plate-kicker">'+(bib?"Historia bíblica":"Cristianismo")+', era '+(i+1)+' de '+eras.length+'</p><h2>'+esc(era.title)+'</h2><p class="plate-sub">'+esc(era.subtitle)+'</p><span class="plate-date">'+esc(dateText(era.date))+'</span><p class="summary">'+esc(era.summary)+'</p>'+diagram(era)+'<div class="cols"><section><h3>Acontecimientos</h3><ol class="history-events">'+ev.map(e=>'<li><details><summary>'+esc(e.title)+(e.dateLabel?' <span class="event-year">'+esc(e.dateLabel)+'</span>':e.date.year!=null?' <span class="event-year">'+esc(fmt(e.date.year))+'</span>':'')+'</summary><div class="event-content"><p>'+esc(e.date.precision==="narrative"?"Acontecimiento del relato bíblico; no se le asigna una fecha histórica.":e.date.precision==="debated"?"Su datación histórica es objeto de debate.":e.date.year!=null?"Fecha orientativa: "+fmt(e.date.year)+".":"La cronología de este acontecimiento no está fijada.")+'</p>'+(e.bookIds?.length?'<p>Lecturas vinculadas: '+e.bookIds.map(b=>'<a href="'+new URL('./index.html',import.meta.url).pathname+'?book='+encodeURIComponent(b)+'&chapter=1">'+esc(b.replace(/-/g," "))+'</a>').join(" · ")+'</p>':'')+'</div></details></li>').join("")+'</ol></section><section><h3>Textos relacionados</h3><ul class="history-books">'+(era.bookIds.length?era.bookIds.map(b=>'<li><a href="'+new URL('./index.html',import.meta.url).pathname+'?book='+encodeURIComponent(b)+'&chapter=1" aria-label="Abrir '+esc(b.replace(/-/g," "))+' en Kol Basilea Lectura">'+esc(b.replace(/-/g," "))+' <span aria-hidden="true">↗</span></a></li>').join(""):'<li>Contexto histórico extrabíblico</li>')+'</ul><p class="link-note">Los enlaces abren el libro en el lector. Su asociación es contextual, no una fecha de composición.</p></section></div><nav class="pager" aria-label="Navegar eras"><button data-id="'+(eras[i-1]?.id||"")+'" '+(i===0?"disabled":"")+'><small>Anterior</small><strong>'+esc(eras[i-1]?.title||"Inicio")+'</strong></button><button data-id="'+(eras[i+1]?.id||"")+'" '+(i===eras.length-1?"disabled":"")+'><small>Siguiente</small><strong>'+esc(eras[i+1]?.title||"Final")+'</strong></button></nav>';const path=basePath+(id===eras[0].id&&location.pathname===basePath?"":slugs[id]+"/");if(location.pathname!==path&&!currentStory&&!fromHistory)history.pushState({era:id},"",path);if(move){const b=$("#era-strip .era[aria-pressed=true]");b?.scrollIntoView({behavior:"smooth",block:"nearest",inline:"center"})}};window.addEventListener("popstate",()=>{const slug=location.pathname.slice(basePath.length).split("/").filter(Boolean)[0];const id=Object.keys(slugs).find(k=>slugs[k]===slug)||eras[0].id;select(id,true,true)});document.body.addEventListener("click",e=>{const b=e.target.closest("button[data-id]");if(b?.dataset.id)select(b.dataset.id,true)});const contentScroll=document.querySelector(".kb-history-app .page");contentScroll?.addEventListener("scroll",()=>{document.querySelector(".kb-history-app")?.classList.toggle("is-reading",contentScroll.scrollTop>100)},{passive:true});select(active)}main().catch(e=>{$("#era-detail").innerHTML='<p>No se pudo cargar la cronología. <button onclick="location.reload()">Reintentar</button></p>';console.error(e)});